    // ---- Top Down Action Prototype ----
    "project.topdownaction.back": "Volver al portfolio",
    "project.topdownaction.title": "Top Down Action Prototype",
    "project.topdownaction.tagline": "Hack n' slash top-down. Prototipado tanto en Unreal Engine como en Unity — Trabajo en proceso.",
    "project.topdownaction.link.itch": "Jugar en itch.io",
    "project.topdownaction.link.steam": "Ver en Steam",
    "project.topdownaction.link.github": "Código en GitHub",
    "project.topdownaction.about.heading": "Sobre el proyecto",
    "project.topdownaction.about.body": "Proyecto personal en proceso con dos prototipos paralelos, uno en Unreal Engine y otro en Unity, para explorar un hack n' slash top-down.",
    "project.topdownaction.role.heading": "Mi rol",
    "project.topdownaction.role.body": "Prototipo de Unreal: mecánicas de gameplay (movimiento, combate y habilidades), game feel, materiales (shaders) e identidad visual, elementos de gameplay basados en física combinados con hack n' slash.\n\nPrototipo de Unity: sistema de movilidad, sistema avanzado de habilidades/estados/efectos que centraliza toda la lógica de gameplay, similar al GAS de Unreal.",
    "project.topdownaction.challenges.heading": "Retos técnicos",
    "project.topdownaction.challenges.item1": "Centralizar habilidades, estados y efectos en un sistema de gameplay reutilizable en Unity.",
    "project.topdownaction.challenges.item2": "Combinar física y hack n' slash sin perder control sobre el game feel.",
    "project.topdownaction.challenges.item3": "Explorar materiales, shaders e identidad visual en el prototipo de Unreal.",
    "project.topdownaction.learned.heading": "Qué aprendí",
    "project.topdownaction.learned.body": "Aprendí a comparar arquitecturas de gameplay entre motores y a separar sistemas para poder iterar con rapidez.",
